explain functionality of this function: int traverseHash(const struct hash_s *hash, int (*fn)(const struct hashRec_s *hashRec))
{
  size_t i, key;

#ifdef DEBUG
  if (config->debug >= 3)
    printf("DEBUG - Traversing hash\n");
#endif

  for (key = 0; key < hash->size; key++)
  {
    if (hash->lists[key] != NULL)
    {
      for (i = 0; i < hash->lists[key]->count; i++)
      {
        if (hash->lists[key]->records[i] != NULL)
        {
          if (fn(hash->lists[key]->records[i]))
            return (FAILED);
        }
      }
    }
  }

  return (TRUE);
}
